#[capability(
    module = "woocommerce",
    id = "list-products",
    display_name = r##"List Products"##,
    description = r##"Lists products a page at a time (`per_page` up to 100, `page` from 1), by `sku`, `type`, `status`, `category`, `tag`, `stock_status`, `on_sale`, price, dates or `search`. A page of fewer than `per_page` products is the last."##
)]
pub async fn list_products(input: ListProductsInput) -> Result<Vec<Product>, AgentError> {
    let connection = kit::require_connection(&input._connection, "WOOCOMMERCE")?;
    input.request()?.send(connection, "WOOCOMMERCE").await
}

impl ListProductsInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = String::from("/wp-json/wc/v3/products");
        let request = kit::Request::new("GET", path)
            .query_opt("context", &self.context)
            .query_opt("page", &self.page)
            .query_opt("per_page", &self.per_page)
            .query_opt("search", &self.search)
            .query_opt("after", &self.after)
            .query_opt("before", &self.before)
            .query_opt("modified_after", &self.modified_after)
            .query_opt("modified_before", &self.modified_before)
            .query_opt("dates_are_gmt", &self.dates_are_gmt)
            .query_each_opt("exclude", &self.exclude)
            .query_each_opt("include", &self.include)
            .query_opt("offset", &self.offset)
            .query_opt("order", &self.order)
            .query_opt("orderby", &self.orderby)
            .query_each_opt("parent", &self.parent)
            .query_each_opt("parent_exclude", &self.parent_exclude)
            .query_opt("brand", &self.brand)
            .query_opt("slug", &self.slug)
            .query_opt("status", &self.status)
            .query_opt("type", &self.r#type)
            .query_opt("sku", &self.sku)
            .query_opt("featured", &self.featured)
            .query_opt("category", &self.category)
            .query_opt("tag", &self.tag)
            .query_opt("shipping_class", &self.shipping_class)
            .query_opt("attribute", &self.attribute)
            .query_opt("attribute_term", &self.attribute_term)
            .query_opt("on_sale", &self.on_sale)
            .query_opt("min_price", &self.min_price)
            .query_opt("max_price", &self.max_price)
            .query_each_opt("include_meta", &self.include_meta)
            .query_each_opt("exclude_meta", &self.exclude_meta)
            .query_opt("image_size", &self.image_size)
            .query_opt("stock_status", &self.stock_status)
            .query_opt("search_sku", &self.search_sku)
            .query_opt("search_name_or_sku", &self.search_name_or_sku)
            .query_each_opt("search_fields", &self.search_fields)
            .query_each_opt("include_status", &self.include_status)
            .query_each_opt("exclude_status", &self.exclude_status)
            .query_each_opt("include_types", &self.include_types)
            .query_each_opt("exclude_types", &self.exclude_types)
            .query_opt("downloadable", &self.downloadable)
            .query_opt("virtual", &self.r#virtual)
            .query_opt("pos_products_only", &self.pos_products_only);
        Ok(request)
    }
}

